NONCANONICAL_DATA:
- reference_cohort_&_imaging: {"dataset_name": "Asan Medical Center (AMC), Jeonbuk National University Hospital (JNUH), Center of Biomedical Research Excellence (COBRE), Neuromorphometry by Computer Algorithm Chicago (NMorphCH), MIND Clinical Imaging Consortium (MCIC), Function Biomedical Informatics Research Network (fBIRN), University of California Los Angeles Consortium for Neuropsychiatric Phenomics LA5c Study (UCLA)", "hc_n": "420", "hc_age": "mean 36.7; sd 11.3", "hc_sex": "M 246 (58.6%)", "imaging_modality": "T1-weighted MRI", "analysis_level": "ROI-level", "preprocessing_pipeline": "FreeSurfer (version 7.1)", "quality_checking": "Yes", "quality_checking_detail": "identified outliers on a criterion of the range of mean ± 3.5 S.D.s of each regional cortical measure across 308 cortical regions. and excluded participants with the total number of identified outliers higher than 8 (the 3rd quartile + 3 × interquartile range).", "site_effect_handling": "Batch-removal", "site_effect_handling_detail": "ComBat harmonization was adopted to adjust for site differences in the neuroimaging data."}
- clinical_application_&_analysis: {"clinical_dataset": "Same as reference dataset", "diseases_studied": "Schizophrenia (SCZ)", "clinical_groups_n": "SCZ: 695", "clinical_groups_age": "mean 36; sd 11.4", "clinical_groups_sex": "M 382 (55%)", "deviation_metric": "z score of the PBSI score... based on a criterion of lower than the mean -1.5 S.D.", "association_analysis": "Spearman's correlation was used to test the association between the PBSI score and clinical variables. and Mann-Whitney U test for comparing deviant and non-deviant patients.", "key_findings_brief": "Patients with SCZ have greater structural variability in the cerebral cortex, and this is associated with lower general intelligence.", "key_findings_detailed": "Patients with SCZ had a greater CV of surface area and cortical thickness than those of healthy controls. All PBSI scores across cortical measures were lower in patients with SCZ than in HCs. In the patient group, the PBSI scores for gray matter volume and all cortical measures taken together positively correlated with the full-scale IQ scores. Patients with deviant PBSI scores for gray matter volume and all cortical measures taken together had lower full-scale IQ scores than those of other patients.", "key_limitations": "small subset of patients for whom the IQ scores were available; did not consider variations from race, education, etc. in harmonization; cumulative exposure to antipsychotics not considered; limited number of cognitive tests.", "application_notes": "The identification of neurobiological biomarkers may contribute to the development of an individualized diagnostic and treatment plan for patients in the future."}
